window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[318]={"id":"318","numero":318,"titre":"LLC — Leucémie Lymphoïde Chronique","objectifs":[{"id":"318-1","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître la définition de la leucémie lymphoïde chronique (LLC)","contenu":"<p>La <strong><span class=\"kw-def\">leucémie lymphoïde chronique</span></strong> (LLC) est une <span class=\"kw-def\">prolifération lymphoïde monoclonale</span> de <strong><span class=\"kw-def\">lymphocytes B matures</span></strong>, de <span class=\"kw-clinique\">petite taille</span>, à <span class=\"kw-clinique\">chromatine mûre et dense</span> et <span class=\"kw-clinique\">rapport nucléocytoplasmique élevé</span>. Les <span class=\"kw-bio\">lymphocytes</span> B clonaux y sont « immortels ».</p>\n      <p>La prolifération <strong>débute dans la moelle osseuse</strong>, puis envahit successivement les autres compartiments :</p>\n      <ul>\n        <li><strong>Moelle osseuse</strong> — origine clonale de la maladie.</li>\n        <li><strong>Sang</strong> — passage circulant, responsable de l'<span class=\"kw-bio\">hyperlymphocytose</span>.</li>\n        <li><strong>Organes lymphoïdes secondaires</strong> — <span class=\"kw-clinique\">ganglions</span> et <span class=\"kw-clinique\">rate</span>.</li>\n      </ul>\n      <p>Dans la <span class=\"kw-def\">classification</span> de l'<span class=\"kw-def\">OMS</span>, la LLC appartient à la <strong>famille des lymphomes</strong>. C'est le <strong><span class=\"kw-def\">syndrome lymphoprolifératif B chronique le plus fréquent</span></strong>.</p>\n      <p>Le diagnostic repose sur <strong>2 critères</strong> ; le couple <span class=\"kw-bio\">NFS-frottis</span> + <span class=\"kw-bio\">immunophénotypage des lymphocytes sanguins</span> suffit à l'affirmer :</p>\n      <table >\n        <thead><tr><th>Critère</th><th>Seuil requis</th></tr></thead>\n        <tbody>\n          <tr><td>Hyperlymphocytose B monoclonale sanguine</td><td><span class=\"kw-chiffre\">&gt; 5 G/L</span>, persistante</td></tr>\n          <tr><td><span class=\"kw-def\">Score de Matutes</span> à l'immunophénotypage</td><td><span class=\"kw-chiffre\">≥ 4/5</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>À retenir.</strong> Le <span class=\"kw-alerte\">myélogramme</span> et la <span class=\"kw-alerte\">biopsie ostéo-médullaire</span> sont <strong>inutiles au diagnostic</strong> de LLC.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 319 — Lymphome malin · 315 — Leucémie aiguë</em></p>","frequence":1},{"id":"318-2","rang":"B","rubrique":"Physiopathologie","titre":"Connaître le caractère clonal de la pathologie et le moyen simple de prouver la clonalité","contenu":"<p>La LLC est une prolifération <strong><span class=\"kw-def\">clonale</span></strong> : toutes les cellules tumorales descendent d'un <strong>unique <span class=\"kw-bio\">lymphocyte</span> B</strong> transformé. Prouver ce caractère clonal est l'étape qui distingue une LLC d'une simple <span class=\"kw-etio\">lymphocytose réactionnelle</span>.</p>\n      <p>Le <strong>moyen simple de prouver la clonalité</strong> est l'<span class=\"kw-bio\">immunophénotypage des lymphocytes sanguins</span> par <strong><span class=\"kw-bio\">cytométrie de flux</span></strong>, via l'analyse des <strong>chaînes légères</strong> du récepteur B (BCR) de surface. Chaque <span class=\"kw-bio\">lymphocyte</span> B exprime une chaîne légère unique, <span class=\"kw-bio\">kappa (κ)</span> ou <span class=\"kw-bio\">lambda (λ)</span>.</p>\n      <table >\n        <thead><tr><th>Population</th><th>Chaînes légères exprimées</th><th>Interprétation</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-bio\">Lymphocytes</span> B <span class=\"kw-def\">normaux</span></td><td>Mélange de clones κ <strong>et</strong> λ</td><td><span class=\"kw-def\">Polyclonalité</span> — population réactionnelle</td></tr>\n          <tr><td><span class=\"kw-bio\">Lymphocytes</span> B de <span class=\"kw-def\">LLC</span></td><td>Un <strong>seul</strong> type — κ <strong>ou</strong> λ exclusivement</td><td><strong><span class=\"kw-def\">Monotypie</span></strong> — signe la <span class=\"kw-def\">monoclonalité</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>En clair.</strong> Une <strong>expression monotypique</strong> κ ou λ par la population lymphocytaire B en excès signe son caractère <strong>monoclonal</strong> — c'est la preuve cytométrique de la clonalité.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 319 — Lymphome malin</em></p>","frequence":1},{"id":"318-3","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les circonstances cliniques du diagnostic de la LLC","contenu":"<p>Le diagnostic de LLC se fait le plus souvent de façon <strong><span class=\"kw-clinique\">fortuite sur un hémogramme</span></strong>, chez un patient <strong>asymptomatique</strong>, dans <span class=\"kw-chiffre\">&gt; 80 %</span> des cas. Hors complication, il n'y a <strong>pas d'<span class=\"kw-alerte\">urgence</span></strong> diagnostique ni thérapeutique.</p>\n      <p><strong><span class=\"kw-def\">Terrain</span> typique</strong> : âge médian <span class=\"kw-chiffre\">72 ans</span> (survient en général après <span class=\"kw-chiffre\">50 ans</span>), <span class=\"kw-clinique\">prédominance masculine</span> (~<span class=\"kw-chiffre\">60 %</span>). La LLC ne se rencontre <span class=\"kw-alerte\">jamais chez l'enfant</span> et est exceptionnelle chez l'adulte jeune.</p>\n      <p><strong>Signes cliniques</strong>, lorsqu'ils existent :</p>\n      <table >\n        <thead><tr><th>Signe</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\">Polyadénopathie</span></td><td><span class=\"kw-clinique\">Adénopathies</span> <strong>superficielles</strong> ; <span class=\"kw-clinique\">fermes</span> ; <span class=\"kw-clinique\">indolores</span> ; <span class=\"kw-clinique\">non compressives</span> ; <span class=\"kw-clinique\">symétriques</span> ; touchant plusieurs aires (cervicales, sus-claviculaires, axillaires, inguinales)</td></tr>\n          <tr><td><span class=\"kw-clinique\">Splénomégalie</span></td><td>Rare au diagnostic ; si isolée, évoquer plutôt un autre syndrome lymphoprolifératif</td></tr>\n          <tr><td><span class=\"kw-clinique\">Hépatomégalie</span></td><td>Rare</td></tr>\n          <tr><td>Signes généraux</td><td><span class=\"kw-clinique\">Fièvre</span> ; <span class=\"kw-clinique\">sueurs nocturnes</span> ; <span class=\"kw-clinique\">amaigrissement</span> — rares au diagnostic, possibles à l'<span class=\"kw-clinique\">évolution</span></td></tr>\n        </tbody>\n      </table>\n      <p>La maladie peut aussi être révélée par une <strong>complication</strong> : <span class=\"kw-clinique\">infection</span> (zona, pneumopathie récidivante), <span class=\"kw-clinique\">cytopénie auto-immune</span> (anémie hémolytique <span class=\"kw-etio\">auto-immune</span>, thrombopénie immunologique), plus rarement un <span class=\"kw-clinique\">syndrome de Richter</span>.</p>\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-alerte\">Drapeau rouge</span>.</strong> Une <span class=\"kw-clinique\">adénopathie</span> <span class=\"kw-alerte\">indurée</span>, <span class=\"kw-alerte\">asymétrique</span> ou à <span class=\"kw-alerte\">croissance rapide du volume</span> doit faire suspecter un <strong><span class=\"kw-clinique\">syndrome de Richter</span></strong> (transformation en lymphome agressif) ou un autre diagnostic.</div>\n      <div class=\"callout callout-warn\"><strong>Dogme EDN.</strong> Toute <span class=\"kw-bio\">hyperlymphocytose</span> <span class=\"kw-chiffre\">&gt; 4 G/L</span> persistante chez un sujet <span class=\"kw-chiffre\">&gt; 60 ans</span> doit faire suspecter une LLC et faire réaliser un <span class=\"kw-bio\">frottis sanguin</span> + un <span class=\"kw-bio\">immunophénotypage des lymphocytes sanguins</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 275 — <span class=\"kw-clinique\">Splénomégalie</span> · 213 — Anémie · 215 — <span class=\"kw-def\">Purpura</span></em></p>","frequence":3},{"id":"318-4","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les circonstances biologiques du diagnostic de la LLC","contenu":"<p>Le tableau <span class=\"kw-ttt\">biologique</span> repose sur la <span class=\"kw-bio\">NFS</span> et sur l'analyse du <strong>frottis sanguin</strong>.</p>\n      <p><strong><span class=\"kw-bio\">Hémogramme</span></strong> : <span class=\"kw-bio\">hyperlymphocytose</span> persistante <span class=\"kw-chiffre\">&gt; 5 G/L</span> (parfois <span class=\"kw-chiffre\">&gt; 100 G/L</span> dans les formes très évoluées), confirmée sur <strong>plusieurs hémogrammes</strong> successifs (persistance <span class=\"kw-chiffre\">&gt; 3 mois</span>). Les autres lignées sont <span class=\"kw-bio\">normales</span>, sauf en cas de complication (<span class=\"kw-bio\">envahissement</span> médullaire, cytopénie <span class=\"kw-etio\">auto-immune</span>).</p>\n      <p><strong>Frottis sanguin</strong> — analyse essentielle. Les <span class=\"kw-bio\">lymphocytes</span> de LLC ont un aspect caractéristique, à distinguer de ceux d'un syndrome mononucléosique :</p>\n      <table >\n        <thead><tr><th>Critère</th><th><span class=\"kw-bio\">Lymphocyte</span> de LLC</th><th>Syndrome mononucléosique</th></tr></thead>\n        <tbody>\n          <tr><td>Aspect</td><td><span class=\"kw-clinique\">Monomorphe</span></td><td>Polymorphe</td></tr>\n          <tr><td>Taille</td><td><span class=\"kw-clinique\">Petite taille</span></td><td>Grande taille</td></tr>\n          <tr><td>Chromatine</td><td><span class=\"kw-clinique\">Mature et dense</span></td><td>Fine</td></tr>\n          <tr><td>Rapport nucléocytoplasmique</td><td><span class=\"kw-clinique\">Élevé</span></td><td>Abaissé</td></tr>\n        </tbody>\n      </table>\n      <p>Les <strong><span class=\"kw-bio\">ombres de Gumprecht</span></strong> — noyaux nus apparaissant par <strong>éclatement des <span class=\"kw-bio\">lymphocytes</span></strong> lors de l'étalement du frottis — sont <span class=\"kw-alerte\">très évocatrices</span> de LLC. La présence de <span class=\"kw-bio\">lymphocytes</span> <span class=\"kw-clinique\">atypiques</span> est possible mais doit rester <span class=\"kw-chiffre\">&lt; 10 %</span> des <span class=\"kw-bio\">lymphocytes</span> totaux.</p>\n      <div class=\"callout callout-warn\"><strong>Piège.</strong> Une proportion de <span class=\"kw-bio\">lymphocytes</span> atypiques <span class=\"kw-alerte\">&gt; 10 %</span> sort du tableau de LLC classique et doit faire évoquer un autre syndrome lymphoprolifératif (lymphome leucémisé).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 212 — <span class=\"kw-bio\">Hémogramme</span> · 316 — Syndrome myélodysplasique · 214 — Thrombopénie</em></p>","frequence":2},{"id":"318-5","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les examens permettant de confirmer le diagnostic de la LLC","contenu":"<p>La confirmation diagnostique repose sur l'<strong><span class=\"kw-bio\">immunophénotypage des lymphocytes sanguins</span></strong>, réalisé par <strong><span class=\"kw-bio\">cytométrie de flux</span></strong>. <span class=\"kw-alerte\">Ni myélogramme ni biopsie ne sont nécessaires.</span></p>\n      <p><strong>Trois utilités</strong> de l'immunophénotypage :</p>\n      <ul>\n        <li>Déterminer la <strong>lignée</strong> de la population en excès — B (<span class=\"kw-bio\">CD19</span>, <span class=\"kw-bio\">CD20</span>) <span class=\"kw-bio\">vs</span> T (<span class=\"kw-bio\">CD3</span>).</li>\n        <li>Prouver la <strong>monoclonalité</strong> — expression monotypique d'une seule chaîne légère (<span class=\"kw-bio\">κ</span> ou <span class=\"kw-bio\">λ</span>).</li>\n        <li><strong>Affirmer la LLC</strong> en cas de population B monoclonale avérée.</li>\n      </ul>\n      <p><strong>Phénotype de la LLC</strong> : <span class=\"kw-bio\">CD19+</span>, <span class=\"kw-bio\">CD20+</span>, <span class=\"kw-bio\">CD5+</span> (le CD5 est normalement un marqueur T — son expression par un <span class=\"kw-bio\">lymphocyte</span> B est une <span class=\"kw-def\">infidélité de lignée</span>), <span class=\"kw-bio\">CD23+</span>, avec <span class=\"kw-def\">monotypie</span> κ ou λ. Le <strong>seuil OMS</strong> diagnostique est de <span class=\"kw-chiffre\">&gt; 5 G/L</span> de <span class=\"kw-bio\">lymphocytes</span> B monoclonaux.</p>\n      <p><strong><span class=\"kw-def\">Score</span> de Matutes (RMH</strong>, <em>Royal Marsden Hospital</em><strong>)</strong> — score <strong>diagnostique</strong> coté de <span class=\"kw-chiffre\">0 à 5</span>, chaque <span class=\"kw-bio\">antigène</span> valant 1 point :</p>\n      <table >\n        <thead><tr><th>Antigène</th><th>Cotation — +1 point si…</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-bio\">CD5</span></td><td>présent</td></tr>\n          <tr><td><span class=\"kw-bio\">CD23</span></td><td>présent</td></tr>\n          <tr><td><span class=\"kw-bio\">Ig de surface</span></td><td>expression faible</td></tr>\n          <tr><td><span class=\"kw-bio\">FMC7</span></td><td>absent</td></tr>\n          <tr><td><span class=\"kw-bio\">CD79b</span></td><td>expression faible</td></tr>\n        </tbody>\n      </table>\n      <table >\n        <thead><tr><th><span class=\"kw-def\">Score</span></th><th>Interprétation</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-chiffre\">4 - 5 / 5</span></td><td><strong>Confirme le diagnostic de LLC</strong></td></tr>\n          <tr><td><span class=\"kw-chiffre\">3 / 5</span></td><td>Zone grise — investigations complémentaires, notamment pour le <span class=\"kw-def\">lymphome du manteau</span></td></tr>\n          <tr><td><span class=\"kw-chiffre\">0 - 2 / 5</span></td><td><span class=\"kw-alerte\">Élimine la LLC</span> — oriente vers un autre syndrome lymphoprolifératif B (lymphome folliculaire, de la zone marginale, du manteau)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Piège.</strong> Le <span class=\"kw-def\">score</span> de Matutes est un score <span class=\"kw-alerte\">diagnostique</span>, et <strong>non pronostique</strong> — ne pas le confondre avec la <span class=\"kw-def\">classification</span> de Binet.</div>\n      <p><strong>Distinction LLC <span class=\"kw-bio\">vs</span> lymphome du manteau</strong> (seul différentiel délicat, lui aussi <span class=\"kw-bio\">CD5+</span>) : le manteau <span class=\"kw-alerte\">n'exprime pas le CD23</span> ; la cytogénétique montre une <strong><span class=\"kw-def\">translocation t(11;14)</span></strong> avec surexpression de la <span class=\"kw-def\">cycline D1</span>.</p>\n      <p><strong>Formes frontières</strong> — clone B de phénotype LLC mais <span class=\"kw-chiffre\">&lt; 5 G/L</span> :</p>\n      <table >\n        <thead><tr><th>Entité</th><th>Définition</th><th>Conduite</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Lymphocytose B monoclonale (MBL)</span></td><td>Clone circulant isolé <span class=\"kw-chiffre\">&lt; 5 G/L</span>, <strong>sans</strong> <span class=\"kw-clinique\">adénopathie</span> ni <span class=\"kw-clinique\">splénomégalie</span> — état « pré-LLC »</td><td><span class=\"kw-def\">Surveillance</span> ; risque de conversion en LLC <span class=\"kw-chiffre\">1-2 %/an</span></td></tr>\n          <tr><td><span class=\"kw-def\">Lymphome lymphocytique</span></td><td>Forme à prédominance <span class=\"kw-etio\">tumorale</span> de LLC — clone <span class=\"kw-chiffre\">&lt; 5 G/L</span> mais <strong>syndrome <span class=\"kw-etio\">tumoral</span> présent</strong></td><td>Prise en charge comme une LLC</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Bilan une fois la LLC confirmée</strong> :</p>\n      <table >\n        <thead><tr><th>Examen</th><th>Recherche</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-bio\">Test direct à l'anti-globuline (Coombs direct)</span></td><td><span class=\"kw-bio\">Anticorps anti-érythrocytaires</span> — peut être positif même sans hémolyse patente, marque un <strong>risque accru</strong> d'<span class=\"kw-clinique\">anémie hémolytique auto-immune</span></td></tr>\n          <tr><td><span class=\"kw-bio\">Électrophorèse des protéines sériques</span></td><td><span class=\"kw-bio\">Hypogammaglobulinémie</span> ± profonde, chez la majorité des patients ; gammapathie monoclonale <span class=\"kw-bio\">IgM ou IgG</span> de faible taux, chez <span class=\"kw-chiffre\">&lt; 10 %</span> des patients</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Examens inutiles au diagnostic.</strong> <span class=\"kw-alerte\">Myélogramme</span> (sauf cytopénie inexpliquée associée), <span class=\"kw-alerte\">biopsie ostéo-médullaire</span>, <span class=\"kw-alerte\">cytoponction ou biopsie ganglionnaire</span> (sauf suspicion de Richter) et <span class=\"kw-alerte\">imagerie systématique</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 319 — Lymphome malin · 315 — Leucémie aiguë</em></p>","frequence":5},{"id":"318-6","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes du traitement de la LLC","contenu":"<p>La <strong><span class=\"kw-def\">classification de Binet</span></strong> est une <span class=\"kw-def\">classification</span> <strong>pronostique</strong> qui guide l'<strong>indication thérapeutique</strong>. Elle repose sur le nombre d'<strong>aires lymphoïdes atteintes</strong> et sur l'<span class=\"kw-bio\">hémogramme</span>.</p>\n      <table >\n        <thead><tr><th><span class=\"kw-def\">Stade</span></th><th>Fréquence</th><th>Critères</th><th>Conduite à tenir</th></tr></thead>\n        <tbody>\n          <tr><td><strong>A</strong></td><td><span class=\"kw-chiffre\">70-80 %</span></td><td><span class=\"kw-chiffre\">&lt; 3</span> aires ganglionnaires atteintes</td><td><span class=\"kw-alerte\">Abstention thérapeutique</span> — <span class=\"kw-def\">surveillance</span> ; espérance de vie comparable à la population générale</td></tr>\n          <tr><td><strong>B</strong></td><td><span class=\"kw-chiffre\">&lt; 20 %</span></td><td><span class=\"kw-chiffre\">≥ 3</span> aires ganglionnaires atteintes</td><td>Traitement <strong>uniquement</strong> en présence de critères d'évolutivité (NCI)</td></tr>\n          <tr><td><strong>C</strong></td><td><span class=\"kw-chiffre\">&lt; 10 %</span></td><td><span class=\"kw-bio\">Anémie</span> <span class=\"kw-chiffre\">&lt; 10 g/dL</span> et/ou <span class=\"kw-bio\">thrombopénie</span> <span class=\"kw-chiffre\">&lt; 100 G/L</span></td><td><strong>Traitement d'emblée</strong></td></tr>\n        </tbody>\n      </table>\n      <p>Les <strong>5 aires lymphoïdes</strong> de Binet : <span class=\"kw-clinique\">cervicale</span>, <span class=\"kw-clinique\">axillaire</span> et <span class=\"kw-clinique\">inguinale</span> (chacune <strong>bilatérale comptant pour 1 aire</strong>), <span class=\"kw-clinique\">rate</span> et <span class=\"kw-clinique\">foie</span>.</p>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/318/binet-aires-lymphoides.png\" alt=\"Schéma des 5 aires lymphoïdes de la classification de Binet : aires cervicale, axillaire et inguinale, plus rate et foie\" loading=\"lazy\">\n        <figcaption>Les 5 aires lymphoïdes de la <span class=\"kw-def\">classification</span> de Binet : cervicale, axillaire, inguinale (chacune bilatérale comptant pour 1 aire), rate et foie. Source : fiche source EDN item 318.</figcaption>\n      </figure>\n      <p><strong>Critères d'évolutivité (NCI)</strong> — déclenchent le traitement d'un <span class=\"kw-def\">stade</span> B :</p>\n      <ul>\n        <li><span class=\"kw-clinique\">Adénopathies</span> <span class=\"kw-clinique\">volumineuses</span> (<span class=\"kw-chiffre\">&gt; 10 cm</span>) ou rapidement progressives.</li>\n        <li><span class=\"kw-clinique\">Hépatomégalie</span> ou <span class=\"kw-clinique\">splénomégalie</span> significative.</li>\n        <li><span class=\"kw-clinique\">Signes généraux</span>.</li>\n        <li><span class=\"kw-bio\">Temps de doublement des lymphocytes</span> <span class=\"kw-chiffre\">&lt; 6 mois</span>.</li>\n        <li>Apparition ou aggravation d'une <span class=\"kw-bio\">anémie</span> ou d'une <span class=\"kw-bio\">thrombopénie</span>.</li>\n      </ul>\n      <p><strong>Moyens thérapeutiques</strong> : le choix est systématiquement validé en <strong><span class=\"kw-def\">RCP</span></strong>, selon l'âge, les <span class=\"kw-def\">comorbidités</span> et les facteurs pronostiques — notamment l'altération du gène <span class=\"kw-def\">TP53</span> (facteur prédictif de mauvaise réponse). Le traitement de référence de 1ʳᵉ ligne était l'<span class=\"kw-ttt\">immunochimiothérapie</span> (anticorps <span class=\"kw-ttt\">anti-CD20</span> + <span class=\"kw-ttt\">chimiothérapie</span>) ; le développement des <span class=\"kw-ttt\">thérapies ciblées</span> a profondément transformé la prise en charge. Le traitement n'est <strong>pas curatif</strong> et environ <span class=\"kw-chiffre\">1/3</span> des patients ne seront jamais traités.</p>\n      <p><strong>Complications structurant l'<span class=\"kw-clinique\">évolution</span></strong> :</p>\n      <table >\n        <thead><tr><th>Complication</th><th>Mécanisme et éléments clés</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\">Infections</span></td><td><strong>1ʳᵉ cause de décès.</strong><br><strong>Hypogammaglobulinémie :</strong> germes <span class=\"kw-etio\">encapsulés</span> — <span class=\"kw-etio\">pneumocoque</span> ; <span class=\"kw-etio\">Haemophilus influenzae</span><br><strong>Déficit immunitaire T</strong> (lié au traitement) : infections virales — <span class=\"kw-etio\">herpès</span> ; <span class=\"kw-etio\">zona</span> — et parasitaires — <span class=\"kw-etio\">Pneumocystis jiroveci</span><br><strong>Neutropénie :</strong> infections bactériennes ; infections <span class=\"kw-etio\">fongiques</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">Cytopénies auto-immunes</span></td><td><strong>AHAI :</strong> anémie hémolytique <span class=\"kw-etio\">auto-immune</span><br><strong>Thrombopénie auto-immune</strong><br><strong><span class=\"kw-def\">Syndrome d'Evans</span> :</strong> association AHAI + thrombopénie auto-immune<br><strong>Érythroblastopénie auto-immune :</strong> anémie avec <span class=\"kw-alerte\">réticulocytes effondrés</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">Syndrome de Richter</span></td><td>Survient chez <span class=\"kw-chiffre\">5-10 %</span> des patients (surtout multi-traités). Transformation en <span class=\"kw-alerte\">lymphome de haut grade</span> ; aggravation des signes généraux + <span class=\"kw-clinique\">adénopathie</span> indurée asymétrique à croissance rapide ; <span class=\"kw-bio\">LDH</span> élevées ; <span class=\"kw-bio\">hypercalcémie</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Repère.</strong> La LLC ne se transforme <span class=\"kw-alerte\">jamais en leucémie aiguë</span> (contrairement à la LMC) — sa seule <span class=\"kw-clinique\">évolution</span> maligne possible est le <span class=\"kw-clinique\">syndrome de Richter</span>.</div>\n      <p><strong>Prévention des infections</strong> : vaccination <span class=\"kw-ttt\">antipneumococcique</span> et <span class=\"kw-ttt\">anti-Haemophilus</span> recommandée dès le diagnostic ; vaccination <span class=\"kw-ttt\">antigrippale</span> annuelle.</p>\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-ci\">Contre-indication</span>.</strong> Les <span class=\"kw-ci\">vaccins vivants</span> sont <strong><span class=\"kw-ci\">contre-indiqués</span></strong> chez le patient atteint de LLC.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 146 — Vaccination</em></p>","frequence":1}],"astuces":[],"strategie":{"redflags":"<ul><li><span class=\"kw-clinique\">Adénopathie indurée, asymétrique ou à croissance rapide</span> + <span class=\"kw-clinique\">aggravation des signes généraux</span> → <span class=\"kw-def\">syndrome de Richter</span> : transformation en <span class=\"kw-alerte\">lymphome de haut grade</span> (<span class=\"kw-bio\">LDH</span> élevées, <span class=\"kw-bio\">hypercalcémie</span>)</li><li><span class=\"kw-alerte\">Cytopénies auto-immunes profondes et rapidement évolutives</span> : <span class=\"kw-def\">AHAI</span>, <span class=\"kw-def\">thrombopénie auto-immune</span>, <span class=\"kw-def\">syndrome d'Evans</span> (AHAI + thrombopénie) ; <span class=\"kw-clinique\">réticulocytes effondrés</span> si érythroblastopénie <span class=\"kw-etio\">auto-immune</span></li><li><span class=\"kw-clinique\">Anémie</span> <span class=\"kw-chiffre\">&lt; 10 g/dL</span> et/ou <span class=\"kw-clinique\">thrombopénie</span> <span class=\"kw-chiffre\">&lt; 100 G/L</span> = <span class=\"kw-def\">stade C de Binet</span> → impose un <span class=\"kw-ttt\">traitement d'emblée</span></li><li><span class=\"kw-clinique\">Infections répétées ou sévères</span> — <span class=\"kw-alerte\">1ʳᵉ cause de décès</span> : <span class=\"kw-bio\">hypogammaglobulinémie</span> → germes <span class=\"kw-etio\">encapsulés</span> (<span class=\"kw-etio\">pneumocoque</span>, <span class=\"kw-etio\">Haemophilus influenzae</span>)</li><li><span class=\"kw-clinique\">Lymphocytes atypiques</span> <span class=\"kw-chiffre\">&gt; 10 %</span> au frottis → hors cadre de la LLC, évoquer un autre <span class=\"kw-def\">syndrome lymphoprolifératif</span></li></ul>","principes":"<p>Hors complication, la LLC n'est <strong>pas une <span class=\"kw-alerte\">urgence</span></strong> thérapeutique. La <span class=\"kw-def\">classification de Binet</span> (pronostique) guide l'<strong>indication</strong> du traitement ; celui-ci n'est <strong>pas curatif</strong> et environ <span class=\"kw-chiffre\">1/3</span> des patients ne seront jamais traités.</p><p><strong><span class=\"kw-def\">Stade</span> A <span class=\"q\">— &lt; 3 aires ganglionnaires (<span class=\"kw-chiffre\">70-80 %</span>)</span></strong></p><ul><li><span class=\"kw-ttt\">Abstention thérapeutique</span> — simple <span class=\"kw-def\">surveillance</span></li><li>Espérance de vie comparable à la <span class=\"kw-clinique\">population générale</span> de même âge</li></ul><p><strong><span class=\"kw-def\">Stade</span> B <span class=\"q\">— <span class=\"kw-chiffre\">≥ 3</span> aires ganglionnaires (&lt;<span class=\"kw-chiffre\"> 20 %</span>)</span></strong></p><ul><li>Traitement <strong>uniquement</strong> si <span class=\"kw-def\">critères d'évolutivité (NCI)</span></li><li><span class=\"kw-clinique\">Adénopathies</span> <span class=\"kw-chiffre\">&gt; 10 cm</span> ou rapidement progressives · <span class=\"kw-clinique\">hépato-splénomégalie</span> · <span class=\"kw-clinique\">signes généraux</span></li><li><span class=\"kw-bio\">Temps de doublement des lymphocytes</span> <span class=\"kw-chiffre\">&lt; 6 mois</span> · apparition / aggravation d'une <span class=\"kw-bio\">anémie</span> ou <span class=\"kw-bio\">thrombopénie</span></li></ul><p><strong><span class=\"kw-def\">Stade</span> C <span class=\"q\">— anémie &lt;<span class=\"kw-chiffre\"> 10 g/dL</span> et/ou thrombopénie &lt; <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>100</span> G/L</span> (&lt;<span class=\"kw-chiffre\"> 10 %</span>)</span></strong></p><ul><li><span class=\"kw-ttt\">Traitement d'emblée</span></li></ul><p><strong>Moyens thérapeutiques</strong></p><ul><li>Choix validé en <span class=\"kw-ttt\">RCP</span> selon l'âge, les <span class=\"kw-def\">comorbidités</span> et les facteurs pronostiques</li><li>Recherche d'une altération de <span class=\"kw-def\">TP53</span> (facteur prédictif de mauvaise réponse)</li><li><span class=\"kw-ttt\">Immunochimiothérapie</span> (anticorps <span class=\"kw-ttt\">anti-CD20</span> + <span class=\"kw-ttt\">chimiothérapie</span>) ou <span class=\"kw-ttt\">thérapies ciblées</span></li></ul><p><strong>Prévention des infections</strong></p><p><span class=\"kw-ci\">Vaccins vivants contre-indiqués</span> chez le patient atteint de LLC</p><ul><li>Vaccination <span class=\"kw-ttt\">antipneumococcique</span> et <span class=\"kw-ttt\">anti-Haemophilus</span> dès le diagnostic</li><li>Vaccination <span class=\"kw-ttt\">antigrippale</span> annuelle</li></ul>","suivi":"<p><strong>LLC <span class=\"kw-def\">stade</span> A / abstention</strong></p><ul><li><span class=\"kw-def\">Surveillance</span> <span class=\"kw-clinique\">clinique</span> + <span class=\"kw-bio\">hémogramme</span> réguliers</li><li><span class=\"kw-bio\">Temps de doublement des lymphocytes</span> — déclenche le traitement si <span class=\"kw-chiffre\">&lt; 6 mois</span></li></ul><p><strong>Lymphocytose B monoclonale (MBL)</strong></p><ul><li>État « <span class=\"kw-def\">pré-LLC</span> » : clone B isolé <span class=\"kw-chiffre\">&lt; 5 G/L</span> sans syndrome <span class=\"kw-etio\">tumoral</span></li><li><span class=\"kw-def\">Surveillance</span> simple — risque de conversion en LLC <span class=\"kw-chiffre\">1-2 %/an</span></li></ul><p><strong><span class=\"kw-def\">Dépistage</span> des complications</strong></p><ul><li><span class=\"kw-bio\">Test de Coombs direct</span> positif → risque accru d'<span class=\"kw-clinique\">anémie hémolytique auto-immune</span></li><li>Surveiller <span class=\"kw-clinique\">cytopénies auto-immunes</span>, <span class=\"kw-clinique\">infections</span> et <span class=\"kw-def\">syndrome de Richter</span></li></ul>"},"liensGlobaux":[{"href":"https://radiopaedia.org/articles/chronic-lymphocytic-leukaemia","label":"Radiopaedia : Chronic lymphocytic leukaemia"},{"href":"https://radiopaedia.org/articles/richter-transformation","label":"Radiopaedia : Richter transformation"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Hyperlymphocytose B monoclonale persistante — Frottis sanguin + immunophénotypage par cytométrie de flux — population B monotypique κ ou λ confirmée","detail":"<h4>Démarche diagnostique — hyperlymphocytose B monoclonale — Seuil OMS <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>5</span> G/L</span> de <span class=\"kw-bio\">lymphocytes</span> B monoclonaux + <span class=\"kw-def\">score</span> de Matutes</h4>","branches":[{"to":"q-matutes","label":"Lymphocytes B monoclonaux > 5 G/L","color":"blue"},{"to":"q-tumoral","label":"Lymphocytes B monoclonaux < 5 G/L","color":"blue"}]},{"id":"q-matutes","kind":"decision","label":"Score de Matutes (RMH) ? — Coté de 0 à 5 : CD5+, CD23+, Ig de surface faible, FMC7 absent, CD79b faible (1 point chacun). Score diagnostique, NON pronostique","branches":[{"to":"t-llc","label":"4-5/5","color":"green"},{"to":"q-manteau","label":"3/5 — zone grise","color":"amber"},{"to":"t-autre-slp","label":"0-2/5","color":"blue"}]},{"id":"t-llc","kind":"terminal","label":"LLC confirmée","color":"green","detail":"<h4>Confirmation</h4><ul><li><span class=\"kw-def\">Score de Matutes</span> <span class=\"kw-chiffre\">≥ 4/5</span> + <span class=\"kw-chiffre\">&gt; 5 G/L</span> de <span class=\"kw-bio\">lymphocytes B monoclonaux</span> → affirme la <span class=\"kw-def\">LLC</span></li></ul><h4>Phénotype</h4><ul><li><span class=\"kw-bio\">CD19+</span>, <span class=\"kw-bio\">CD20+</span>, <span class=\"kw-bio\">CD5+</span> (infidélité de lignée), <span class=\"kw-bio\">CD23+</span> ; <span class=\"kw-def\">monotypie</span> κ ou λ</li></ul><h4>Examens inutiles</h4><ul><li><span class=\"kw-bio\">Myélogramme</span> et <span class=\"kw-bio\">biopsie ostéo-médullaire</span> inutiles au diagnostic</li></ul><h4>Renvoi</h4><ul><li>Item 319 (lymphome malin) · Item 315 (leucémie aiguë)</li></ul>"},{"id":"q-manteau","kind":"decision","label":"CD23 et cytogénétique ? — Distinguer la LLC d'un lymphome du manteau, lui aussi CD5+","branches":[{"to":"t-manteau","label":"CD23 négatif · t(11;14) · cycline D1+","color":"amber"},{"to":"t-llc-confirme","label":"CD23 positif · pas de t(11;14)","color":"green"}]},{"id":"t-manteau","kind":"terminal","label":"Lymphome du manteau","color":"amber","detail":"<h4>Argument clé</h4><ul><li>Le <span class=\"kw-def\">lymphome du manteau</span> exprime aussi le <span class=\"kw-bio\">CD5</span> mais <span class=\"kw-bio\">n'exprime pas le CD23</span></li></ul><h4>Cytogénétique</h4><ul><li><span class=\"kw-def\">Translocation t(11;14)</span> avec surexpression de la <span class=\"kw-def\">cycline D1</span> (présente dans ~<span class=\"kw-chiffre\">95 %</span> des cas)</li></ul><h4>Conduite</h4><ul><li>Ce n'est <strong>pas</strong> une LLC → prise en charge spécifique du lymphome du manteau</li></ul><h4>Renvoi</h4><ul><li>Item 319 (lymphome malin)</li></ul>"},{"id":"t-llc-confirme","kind":"terminal","label":"LLC retenue (doute levé)","color":"green","detail":"<h4>Lever de doute</h4><ul><li><span class=\"kw-bio\">CD23+</span> et absence de <span class=\"kw-def\">t(11;14)</span> / <span class=\"kw-def\">cycline D1</span> → écarte le <span class=\"kw-def\">lymphome du manteau</span></li></ul><h4>Conclusion</h4><ul><li>Diagnostic de <span class=\"kw-def\">LLC</span> retenu</li></ul>"},{"id":"t-autre-slp","kind":"terminal","label":"Autre syndrome lymphoprolifératif B","color":"amber","detail":"<h4>Interprétation</h4><ul><li><span class=\"kw-def\">Score</span> <span class=\"kw-chiffre\">0-2/5</span> → <span class=\"kw-alerte\">élimine la LLC</span></li></ul><h4>Orientation</h4><ul><li>Phase leucémique d'un autre <span class=\"kw-def\">lymphome non hodgkinien B</span> : <span class=\"kw-etio\">lymphome folliculaire</span>, <span class=\"kw-etio\">de la zone marginale</span>, <span class=\"kw-etio\">du manteau</span></li></ul><h4>Renvoi</h4><ul><li>Item 319 (lymphome malin)</li></ul>"},{"id":"q-tumoral","kind":"decision","label":"Syndrome tumoral associé ? — Adénopathie ou splénomégalie cliniquement décelable","branches":[{"to":"t-mbl","label":"Absent — clone circulant isolé","color":"blue"},{"to":"t-lympho-lymphocytique","label":"Présent","color":"amber"}]},{"id":"t-mbl","kind":"terminal","label":"Lymphocytose B monoclonale (MBL)","color":"blue","detail":"<h4>Définition</h4><ul><li>Clone B circulant isolé <span class=\"kw-chiffre\">&lt; 5 G/L</span>, <strong>sans</strong> <span class=\"kw-clinique\">adénopathie</span> ni <span class=\"kw-clinique\">splénomégalie</span> — état « <span class=\"kw-def\">pré-LLC</span> »</li></ul><h4>Conduite</h4><ul><li><span class=\"kw-def\">Surveillance</span> simple ; risque de conversion en LLC <span class=\"kw-chiffre\">1-2 %/an</span></li></ul>"},{"id":"t-lympho-lymphocytique","kind":"terminal","label":"Lymphome lymphocytique","color":"amber","detail":"<h4>Définition</h4><ul><li>Clone <span class=\"kw-chiffre\">&lt; 5 G/L</span> mais <span class=\"kw-clinique\">syndrome tumoral présent</span> — forme à prédominance <span class=\"kw-etio\">tumorale</span> de LLC</li></ul><h4>Conduite</h4><ul><li>Prise en charge comme une <span class=\"kw-def\">LLC</span></li></ul>"}]},"cards":[{"i":"4172b9fdfb84","n":318,"o":"318-1","u":"Diagnostic positif","t":"Connaître la définition de la leucémie lymphoïde chronique (LLC)","q":"Quelle est la définition de la leucémie lymphoïde chronique (LLC) ?","a":"<p>La leucémie lymphoïde chronique (LLC) est une <strong>prolifération lymphoïde monoclonale de lymphocytes B matures</strong>, de petite taille, à chromatine mûre et dense, et à rapport nucléocytoplasmique élevé. Ces lymphocytes B clonaux sont considérés comme « immortels ».</p>"},{"i":"4e530572c48a","n":318,"o":"318-1","u":"Diagnostic positif","t":"Connaître la définition de la leucémie lymphoïde chronique (LLC)","q":"Quel est le diagnostic positif de la leucémie lymphoïde chronique (LLC) ?","a":"<p>Le diagnostic de LLC repose sur <strong>deux critères</strong> affirmés par le couple NFS-frottis et l'immunophénotypage des lymphocytes sanguins :</p><ul><li>Une <strong>hyperlymphocytose B monoclonale sanguine &gt; 5 G/L</strong>, persistante.</li><li>Un <strong>score de Matutes à l'immunophénotypage ≥ 4/5</strong>.</li></ul><p>Il est important de noter que le <strong>myélogramme et la biopsie ostéo-médullaire sont inutiles au diagnostic</strong> de LLC.</p>"},{"i":"ecb5e309334e","n":318,"o":"318-1","u":"Diagnostic positif","t":"Connaître la définition de la leucémie lymphoïde chronique (LLC)","q":"Où débute et se diffuse la prolifération cellulaire caractéristique de la leucémie lymphoïde chronique (LLC) ?","a":"<p>La prolifération débute dans la <strong>moelle osseuse</strong>, puis envahit successivement les autres compartiments :</p><ul><li>La <strong>moelle osseuse</strong> (origine clonale).</li><li>Le <strong>sang</strong> (responsable de l'hyperlymphocytose).</li><li>Les <strong>organes lymphoïdes secondaires</strong> (ganglions et rate).</li></ul>"},{"i":"012217aeb35f","n":318,"o":"318-3","u":"Diagnostic positif","t":"Connaître les circonstances cliniques du diagnostic de la LLC","q":"Quels sont les signes cliniques pouvant être observés au diagnostic de la leucémie lymphoïde chronique (LLC), s'ils existent ?","a":"<ul><li>Une <strong>polyadénopathie</strong>: adénopathies superficielles, fermes, indolores, non compressives, symétriques, touchant plusieurs aires (cervicales, sus-claviculaires, axillaires, inguinales).</li><li>Une <strong>splénomégalie</strong> (rare au diagnostic ; si isolée, évoquer plutôt un autre syndrome lymphoprolifératif).</li><li>Une <strong>hépatomégalie</strong> (rare).</li><li>Des <strong>signes généraux</strong> (fièvre, sueurs nocturnes, amaigrissement) sont rares au diagnostic mais possibles à l'évolution.</li></ul>"},{"i":"383724ebfb63","n":318,"o":"318-3","u":"Diagnostic positif","t":"Connaître les circonstances cliniques du diagnostic de la LLC","q":"Quelle est la principale circonstance de découverte de la leucémie lymphoïde chronique (LLC) ?","a":"<p>Le diagnostic de LLC est le plus souvent <strong>fortuit</strong>, lors d'un <strong>hémogramme</strong> réalisé chez un patient <strong>asymptomatique</strong> (dans plus de 80% des cas).</p>"},{"i":"62721e4becd1","n":318,"o":"318-3","u":"Diagnostic positif","t":"Connaître les circonstances cliniques du diagnostic de la LLC","q":"Quelles complications peuvent révéler une leucémie lymphoïde chronique (LLC) ?","a":"<ul><li>Une <strong>infection</strong> (ex: zona, pneumopathie récidivante).</li><li>Une <strong>cytopénie auto-immune</strong> (ex: anémie hémolytique auto-immune, thrombopénie immunologique).</li><li>Plus rarement, un <strong>syndrome de Richter</strong>.</li></ul>"},{"i":"74ee0c6d8642","n":318,"o":"318-3","u":"Diagnostic positif","t":"Connaître les circonstances cliniques du diagnostic de la LLC","q":"Dans quel contexte doit-on suspecter une leucémie lymphoïde chronique (LLC) et quels examens complémentaires réaliser ?","a":"<p>Toute <strong>hyperlymphocytose > 4 G/L persistante</strong> chez un sujet <strong>> 60 ans</strong> doit faire suspecter une LLC. Il convient alors de réaliser un <strong>frottis sanguin</strong> et un <strong>immunophénotypage des lymphocytes sanguins</strong>.</p>"},{"i":"eb090f0fe510","n":318,"o":"318-3","u":"Diagnostic positif","t":"Connaître les circonstances cliniques du diagnostic de la LLC","q":"Quel est le terrain épidémiologique typique de la leucémie lymphoïde chronique (LLC) ?","a":"<p>La LLC survient généralement après 50 ans, avec un <strong>âge médian de 72 ans</strong>. Il existe une <strong>prédominance masculine</strong> (~60%). Elle ne se rencontre jamais chez l'enfant et est exceptionnelle chez l'adulte jeune.</p>"},{"i":"08a464c3c192","n":318,"o":"318-4","u":"Diagnostic positif","t":"Connaître les circonstances biologiques du diagnostic de la LLC","q":"Quelle structure caractéristique observée sur le frottis sanguin est très évocatrice d'une LLC ?","a":"<p>Les <strong>ombres de Gumprecht</strong> sont très évocatrices d'une LLC. Ce sont des noyaux nus apparaissant par éclatement des lymphocytes lors de l'étalement du frottis.</p>"},{"i":"24f65a550db0","n":318,"o":"318-4","u":"Diagnostic positif","t":"Connaître les circonstances biologiques du diagnostic de la LLC","q":"Quel est le critère biologique essentiel pour le diagnostic positif de la Leucémie Lymphoïde Chronique (LLC) sur l'hémogramme ?","a":"<p>Le critère biologique essentiel est une <strong>hyperlymphocytose persistante &gt; 5 G/L</strong>, confirmée sur plusieurs hémogrammes successifs avec une persistance <strong>&gt; 3 mois</strong>.</p>"},{"i":"4bacb836c173","n":318,"o":"318-4","u":"Diagnostic positif","t":"Connaître les circonstances biologiques du diagnostic de la LLC","q":"Comment apparaissent les autres lignées sanguines dans l'hémogramme d'une LLC non compliquée ?","a":"<p>Les autres lignées sanguines (érythrocytaire et myéloïde) sont généralement <strong>normales</strong>, sauf en cas de complication comme un envahissement médullaire ou une cytopénie auto-immune.</p>"},{"i":"a65405616cc9","n":318,"o":"318-4","u":"Diagnostic positif","t":"Connaître les circonstances biologiques du diagnostic de la LLC","q":"Quelles sont les caractéristiques morphologiques des lymphocytes observés sur le frottis sanguin qui sont évocatrices d'une LLC, par rapport à un syndrome mononucléosique ?","a":"<ul><li><strong>Aspect</strong> : <strong>monomorphe</strong> dans la LLC, polymorphe dans le syndrome mononucléosique.</li><li><strong>Taille</strong> : <strong>petite taille</strong> dans la LLC, grande taille dans le syndrome mononucléosique.</li><li><strong>Chromatine</strong> : <strong>mature et dense</strong> dans la LLC, fine dans le syndrome mononucléosique.</li><li><strong>Rapport nucléocytoplasmique</strong> : <strong>élevé</strong> dans la LLC, abaissé dans le syndrome mononucléosique.</li></ul>"},{"i":"e1c61a13add0","n":318,"o":"318-4","u":"Diagnostic positif","t":"Connaître les circonstances biologiques du diagnostic de la LLC","q":"Quelle proportion de lymphocytes atypiques sur le frottis sanguin doit faire remettre en question un diagnostic classique de LLC ?","a":"<p>Une proportion de lymphocytes atypiques <strong>&gt; 10 %</strong> des lymphocytes totaux doit faire évoquer <strong>un autre syndrome lymphoprolifératif</strong> (par exemple, un lymphome leucémisé) et sortir du tableau de LLC classique.</p>"}]};